window.WOW_GEAR_SETS_ITEM_MAP = {};
window.WOW_GEAR_SETS.forEach(function (set) {
  (set.pieces || []).forEach(function (p) {
    window.WOW_GEAR_SETS_ITEM_MAP[p.itemId] = {
      setId: set.id,
      setName: set.name,
      setKind: set.kind,
      piecesCount: set.piecesCount,
      className: set.className,
      slotName: p.slotName
    };
  });
});
